/**
 * Curated library of chemical species used by simulations, lessons, and
 * concept pages. Every entry is a molecular graph (atoms + bond orders +
 * charge) — 3D geometry is generated by the VSEPR layout engine, so there is
 * a single source of truth for structure.
 *
 * Adding a new molecule = adding one entry here. It immediately becomes
 * available in the Molecule Builder presets, the Lewis studio, VSEPR lab,
 * polarity explorer, lesson embeds, and search.
 */

import { Species, speciesFrom } from "./lewis";

export interface MoleculeDef {
  id: string;
  name: string;
  /** Optional display formula override (usually computed from the graph). */
  formula?: string;
  charge: number;
  atoms: Array<[id: string, element: string]>;
  bonds: Array<[a: string, b: string, order: number]>;
  /** Alternative resonance structures (same atoms, different bond orders). */
  resonance?: Array<Array<[a: string, b: string, order: number]>>;
  note: string;
  tags: string[];
}

/* Helper for compact atom/bond lists */
const H = (n: number, prefix = "H") =>
  Array.from({ length: n }, (_, i) => [`${prefix}${i + 1}`, "H"] as [string, string]);

