export const MOLECULE_MAP = new Map(MOLECULES.map((m) => [m.id, m]));

export function getMolecule(id: string): MoleculeDef | undefined {
  return MOLECULE_MAP.get(id);
}

export function moleculeToSpecies(def: MoleculeDef, resonanceIndex = 0): Species {
  const bonds =
    resonanceIndex > 0 && def.resonance && def.resonance[resonanceIndex - 1]
      ? def.resonance[resonanceIndex - 1]
      : def.bonds;
  return speciesFrom(
    def.atoms.map(([id, element]) => ({ id, element })),
    bonds,
    def.charge
  );
}

